import { test,expect } from '@playwright/test';
import { start,settled,enterBoss,winBoss,restore } from './helpers.js';
import { SAVE_KEY } from '../src/progress.js';
test('complete story: four bosses, every scholar, verified research, Eclipse and ending',async({page})=>{
 const errors=[];page.on('pageerror',e=>errors.push(e.message));await start(page);
 for(const id of ['form','division','memory']){await enterBoss(page,id);await page.screenshot({path:`qa/boss-${id}.png`});await winBoss(page,id,{wrong:id==='memory',lose:id==='form'});await restore(page,id);}
 await page.getByRole('button',{name:'The seal of three truths',exact:true}).click();await expect(page.locator('#panel-title')).toHaveText('An oath fulfilled');await page.getByRole('button',{name:'Face the Nameless Exile',exact:true}).click();await winBoss(page,'exile');await page.getByRole('button',{name:'Read the Exile’s fragment'}).click();await expect(page.locator('#codex-body')).toContainText('311');await expect(page.locator('#codex-body')).toContainText('not a defect classification');await page.getByRole('button',{name:'Close Research Codex'}).click();await page.getByRole('button',{name:'Enter the Hidden Archive',exact:true}).click();await page.getByRole('button',{name:'Continue the revelation'}).click();await page.getByRole('button',{name:'Continue the revelation'}).click();await page.getByRole('button',{name:'Unite the evidence'}).click();await expect(page.locator('#codex')).not.toBeVisible();await expect(page.locator('#panel-title')).toHaveText('Let their names remain');await page.getByRole('button',{name:'Explore the research',exact:true}).click();await expect(page.locator('#codex-body')).toContainText('88.12%');await expect(page.locator('#codex-body')).toContainText('do not prove overall improvement');await expect(page.locator('#codex-body')).toContainText('311');await expect(page.locator('.research-chart .main-svg').first()).toBeVisible();await page.screenshot({path:'qa/ending-research.png'});
 expect(await page.evaluate(key=>JSON.parse(localStorage.getItem(key)).ended,SAVE_KEY)).toBe(true);await page.reload();await page.getByRole('button',{name:'Continue Journey',exact:true}).click();await expect(page.locator('#panel-title')).toHaveText('The stones were never lost');expect(errors).toEqual([]);
});

test('nonlinear order and optional Codex: stones alone open the secret seal',async({page})=>{await start(page);for(const id of ['memory','division','form']){await enterBoss(page,id);await winBoss(page,id);await restore(page,id,{research:false});}await page.getByRole('button',{name:'The seal of three truths',exact:true}).click();await expect(page.getByRole('button',{name:'Face the Nameless Exile',exact:true})).toBeVisible();expect(await page.evaluate(()=>Object.values(window.__game.state().bosses).every(b=>!b.revealed))).toBe(true);});

for(const order of [['form','memory','division'],['division','form','memory'],['division','memory','form'],['memory','form','division']])test(`all-order progression: ${order.join(' → ')}`,async({page})=>{
 await start(page);for(const id of order){await enterBoss(page,id);await winBoss(page,id);await restore(page,id,{research:false});}await page.getByRole('button',{name:'The seal of three truths',exact:true}).click();await expect(page.getByRole('button',{name:'Face the Nameless Exile',exact:true})).toBeVisible();
});
